          </section>`).join('') || '<p class="text-xs text-base-content/40">No tool events.</p>'}
      </div>
      <footer class="px-4 py-3 border-t border-white/10 text-[11px] text-base-content/40">
        MOCK: full payloads are the ones posted to <code>/tool-events</code>.
      </footer>
    </aside>`
}

function render() {
  renderFeed()
  renderDrawer()
  document.querySelectorAll('[data-act="width"]').forEach(button => {
    button.setAttribute('aria-pressed', button.dataset.width === state.width ? 'true' : 'false')
  })
  const channelButton = document.querySelector('[data-act="channel"]')
  if (channelButton) {
    channelButton.setAttribute('aria-pressed', state.mode === 'channel' ? 'true' : 'false')
    channelButton.style.color = state.mode === 'channel' ? '#c7d2fe' : ''
    channelButton.style.borderColor = state.mode === 'channel' ? 'rgba(99,102,241,.6)' : ''
  }
  const streamButton = document.querySelector('[data-act="stream"]')
  if (streamButton) streamButton.disabled = state.streaming
  persist()
}

/* Re-render while keeping keyboard focus on the control the user activated */
let focusKey = null
function paint() {
  const key = focusKey || document.activeElement?.dataset?.key || null
  render()
  if (key) document.querySelector(`[data-key="${CSS.escape(key)}"]`)?.focus({ preventScroll: true })
  focusKey = null
}

/* ═════════════════════════════════════════════════════════════════════
   E. ACTIONS
   ═════════════════════════════════════════════════════════════════════ */
const toast = (text, kind = 'info') => {
  const el = document.createElement('div')
  el.className = 'toast'
  el.dataset.kind = kind
  el.setAttribute('role', 'status')
  el.textContent = text
  document.body.appendChild(el)
  setTimeout(() => el.remove(), 2200)
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms))

async function loadFeed({ empty = false, fail = false } = {}) {
  state.status = 'loading'
  state.menu = null
  paint()
  try {
    const res = await mockFetch(`/api/chats/c_dev/messages?${empty ? 'empty=1&' : ''}${fail ? 'fail=1' : ''}`)
    const data = await res.json()
    if (!res.ok) { state.status = 'error'; state.messages = []; paint(); return }
    state.messages = data
    DB.messages = data
    state.status = 'idle'
    paint()
  } catch {
    state.status = 'error'
    paint()
  }
}

const actions = {
  'toggle-panel': (id) => {
    const index = state.expanded.indexOf(id)
    if (index >= 0) state.expanded.splice(index, 1)
    else state.expanded.push(id)
  },
  'toggle-tool': (_, toolCallId) => {
    const index = state.openTools.indexOf(toolCallId)
    if (index >= 0) state.openTools.splice(index, 1)
    else state.openTools.push(toolCallId)
  },
  menu: (id) => { state.menu = state.menu === id ? null : id },
  drawer: (id) => { state.drawer = id; state.menu = null },
  'close-drawer': () => { state.drawer = null },
  width: (width) => { state.width = width },
  channel: () => { state.mode = state.mode === 'channel' ? 'chat' : 'channel' },
  copy: async (id) => {
    const message = state.messages.find(m => m.doc_id === id)
    const text = message?.content || ''
    try { await navigator.clipboard.writeText(text); toast('Copied to clipboard') }
    catch { toast('Clipboard blocked by the browser', 'error') }
  },
  source: (id) => {
    state.sourceView = state.sourceView === id ? null : id
    state.menu = null
  },
  'toggle-seen': async (id) => {
    const message = state.messages.find(m => m.doc_id === id)
    if (!message) return
    const readBy = message.read_by || []
    const next = readBy.includes(ME.username)
      ? readBy.filter(u => u !== ME.username)
      : [...readBy, ME.username]
    await mockFetch(`/api/chats/c_dev/messages/${id}`, { method: 'PATCH', body: JSON.stringify({ read_by: next }) })
    state.messages = [...DB.messages]
    paint()
  },
  delete: async (id) => {
    state.menu = null
    if (!confirm('Delete this message? (mock — no undo)')) return
    await mockFetch(`/api/chats/c_dev/messages/${id}`, { method: 'DELETE' })
    state.expanded = state.expanded.filter(x => x !== id)
    state.messages = [...DB.messages]
    paint()
    toast('Message deleted')
  },
  stop: async (id) => {
    await mockFetch(`/api/chats/c_dev/messages/${id}`, { method: 'PATCH', body: JSON.stringify({ done: true }) })
    state.streaming = false
    state.messages = [...DB.messages]
    paint()
    toast('Run cancelled')
  },
  reset: () => {
    localStorage.removeItem(STORAGE_KEY)
    DB.messages = seedMessages()
    const keepWidth = state.width
    state = { ...defaultState(), width: keepWidth, messages: [...DB.messages] }
    paint()
    toast('Mock reset')
  }
}

/* Scripted run: appends tool events through the mock API, one step at a time,
   so the strip can be watched updating live (last tool + totals). */
const STEPS = [
  { after: 500, event: { tool: 'read_file', status: 'running', request: { path: 'src/components/ChatEntry.vue' } } },
  { after: 900, close: { status: 'done', duration_ms: 410, response: '312 lines' } },
  { after: 500, event: { tool: 'grep', status: 'running', request: { pattern: 'eventsOpen', glob: 'src/**/*.vue' } } },
  { after: 850, close: { status: 'done', duration_ms: 240, response: '7 matches' } },
  { after: 500, event: { tool: 'bash', status: 'running', request: { command: 'pnpm test --run ChatEntry' } } },
  { after: 1100, close: { status: 'error', duration_ms: 1180, error: 'Command failed with exit code 1: 2 tests failed' } },
  { after: 400, event: { tool: 'write_file', status: 'running', request: { path: 'src/components/ChatEntry.vue' } } },
  { after: 1200, close: { status: 'done', duration_ms: 520, response: 'written · 318 lines' } }
]

async function streamRun() {
  if (state.streaming) return
  const target = state.messages.find(m => !m.done) || state.messages[state.messages.length - 1]
  if (!target) return

  state.streaming = true
  state.expanded = state.expanded.includes(target.doc_id) ? state.expanded : [...state.expanded, target.doc_id]
  paint()

  try {
    await mockFetch(`/api/chats/c_dev/messages/${target.doc_id}`, {
      method: 'PATCH',
      body: JSON.stringify({ done: false, content: target.content || '' })
    })

    for (const step of STEPS) {
      await sleep(step.after)
      if (step.event) {
        const res = await mockFetch(`/api/chats/c_dev/messages/${target.doc_id}/tool-events`, {
          method: 'POST', body: JSON.stringify(step.event)
        })
        const payload = await res.json()
        const running = (DB.messages.find(m => m.doc_id === target.doc_id)?.tool_events || []).slice(-1)[0]
        step.toolCallId = payload.event?.tool_call_id || running?.tool_call_id
      } else if (step.close && step.toolCallId) {
        await mockFetch(`/api/chats/c_dev/messages/${target.doc_id}/tool-events/${step.toolCallId}`, {
          method: 'PATCH', body: JSON.stringify(step.close)
        })
      }
      state.messages = [...DB.messages]
      paint()
    }

    await mockFetch(`/api/chats/c_dev/messages/${target.doc_id}`, {
      method: 'PATCH',
      body: JSON.stringify({
        done: true,
        content: 'Run finished. The strip reported **each** execution as it happened — the last one on screen, the totals beside it — and the full wall stayed one click away.',
        lifecycle_events: [{ run_id: 'run_live', status: 'done', duration_ms: 6420 }],
        updated_at: new Date(T0 + 120 * 1000).toISOString()
      })
    })
    state.messages = [...DB.messages]
    toast('Run finished')
  } finally {
    state.streaming = false
    paint()
  }
}

/* ═════════════════════════════════════════════════════════════════════
   F. EVENTS + BOOT
   ═════════════════════════════════════════════════════════════════════ */
document.addEventListener('click', (ev) => {
  const el = ev.target.closest('[data-act]')

  // Any click outside the open ⋯ menu closes it
  if (state.menu && !ev.target.closest('.menu') && !ev.target.closest('[data-act="menu"]')) {
    state.menu = null
    paint()
  }
  if (!el) return

  const { act, id } = el.dataset
  focusKey = el.dataset.key || null

  if (act === 'width') return actions.width(el.dataset.width) || paint()
  if (act === 'load') return loadFeed()
  if (act === 'load-empty') return loadFeed({ empty: true })
  if (act === 'load-fail') return loadFeed({ fail: true })
  if (act === 'stream') return streamRun()
  if (act === 'toggle-tool') return actions['toggle-tool'](id, el.dataset.tool) || paint()
  if (act === 'toggle-panel') {
    actions['toggle-panel'](id)
    state.menu = null
    return paint()
  }
  const handler = actions[act]
  if (!handler) return
  const result = handler(id)
  if (result && result.then) return result.then(() => paint())
  paint()
})

document.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape') {
    if (state.drawer) { state.drawer = null; focusKey = null; return paint() }
    if (state.menu) { state.menu = null; return paint() }
  }
})

document.querySelector('[data-act="channel"]').addEventListener('click', () => {})
// Channel button lives in the toolbar → handled by the delegation above.

;(async function boot() {
  const restored = hydrate()
  await loadFeed()
  if (restored) toast('State restored from localStorage')
})()
</script>
</body>
</html>
